"""Build a readable static monograph; all data and browser dependencies are local."""
from pathlib import Path
from html import escape
import json
from refinement_content import refine_chapters, refine_shell
ROOT=Path(__file__).resolve().parents[1]
ASSET=ROOT.name
def eq(tex,definitions=''):
 return '<div class="equation"><div class="math display">'+escape(tex)+'</div></div>'+('<p class="equation-definitions">'+definitions+'</p>' if definitions else '')
def source(chapter):
 return f'<p class="source">Method: <a href="{ASSET}/cpi-reference-paper.pdf">Statistics Canada, CPI Reference Paper (2023)</a>, {chapter}. Original teaching examples and figures on this page are illustrative.</p>'
def official():
 return '<p class="source">Source: <a href="https://doi.org/10.25318/1810000401-eng">Statistics Canada, Table 18-10-0004-01</a>; local SDMX extraction. Calculations and visualization implemented for this study.</p>'
def lab(title,content,tag='ILLUSTRATIVE EXPERIMENT'):
 return f'<div class="lab"><div class="lab-head"><span class="eyebrow">{tag}</span><h3>{title}</h3></div>{content}</div>'
def player(id,title):
 return f'<div class="player" id="{id}" aria-label="{title}"><div class="stages"></div><div class="stage-detail" aria-live="polite"></div><div class="player-controls"><button type="button" class="play">Play</button><button type="button" class="restart">Restart</button><label>Stage <input class="timeline" type="range" min="0" value="0" step="0.01" aria-label="{title} timeline"></label><output class="stage-number"></output></div></div>'
SECTIONS=[]
def section(num,title,deck,body):SECTIONS.append((num,title,deck,body))

section(1,'The price of an ordinary basket','Start with a receipt. Keep the shopping list still. Let only prices move.', '''
<p class="lead">If a household buys approximately the same basket of goods and services over time, how much more—or less—does that basket cost?</p>
<p>Begin with two cartons of milk, three loaves of bread and two kilograms of apples. At the first month’s prices, milk costs 2 × $4 = $8, bread costs 3 × $3 = $9 and apples cost 2 × $5 = $10. The basket costs $27. If every price rises by 10%, the same quantities cost $29.70. The additional $2.70 divided by the original $27 gives 0.10, or 10%.</p>
'''+lab('Your two-month shopping receipt','''<div class="split"><div><div class="table-wrap"><table id="basket-inputs"><caption>Fictional retail prices; quantities are fixed across the two months.</caption><thead><tr><th>Item</th><th>Quantity</th><th>Month 1, $/unit</th><th>Month 2, $/unit</th></tr></thead><tbody></tbody></table></div><p class="hint">Change any price or quantity. A quantity change applies to <em>both</em> receipts, preserving a fixed basket.</p></div><div class="receipt" id="receipt" aria-live="polite"></div></div><div id="basket-chart" class="chart compact"></div>''')+eq(r'C_0=\sum_i p_i^0q_i,\quad C_1=\sum_i p_i^1q_i,\quad \Delta\%=100\left(\frac{C_1}{C_0}-1\right)', 'C is total basket cost in dollars; p is a dollar price per unit; q is the number of those units; i identifies an item. Superscripts identify months, not powers.')+'''
<p>The official Canadian CPI expands this idea across household consumption. It samples product offers, adjusts for quality differences, combines price changes within groups and then weights groups by expenditure. A household can spend more because prices rise, quantities rise, or both. Holding quantities fixed isolates the first mechanism.</p>
<div id="basket-gallery" class="basket-gallery" aria-label="Illustrated representatives of household consumption"></div>
<p class="source">Miniature SVG products are original illustrations. They represent examples of consumption, not the complete official sample.</p>'''+source('Chapters 1, 3 and 6'))

section(2,'An index is a scale, not a price','Dollar costs, relative changes and inflation rates answer different questions.',eq(r'I_t=100\frac{C_t}{C_0}', 'Iₜ is a dimensionless index at time t. Cₜ is the cost of the fixed basket at t; C₀ is its reference cost. At the reference date Cₜ = C₀, so I₀ = 100.')+'''
<p>Dividing costs cancels dollars. Milk cartons, kilowatt-hours and bus trips have different physical units, but their expenditure totals share a dollar unit. Indexing then provides a common scale. A basket that rises from $27 to $29.70 moves from index 100 to 110; its price change is 10%, whichever currency denomination is used.</p>
<div class="three"><div class="note peach"><h3>Index reference</h3><p>The scale of published levels: generally <b>2002 = 100</b>. The annual average of the reference year is 100; every month in that year need not be 100.</p></div><div class="note green"><h3>Weight reference</h3><p>The expenditure pattern supplying the basket: <b>2025 expenditures</b> for the May 2026 update.</p></div><div class="note blue"><h3>Price reference</h3><p>The denominator prices for a comparison. <b>April 2026</b> is the new basket’s link month. It is not a new 2002-style normalization.</p></div></div>
'''+lab('Move a basket along the index scale','''<label>Current basket cost <input type="range" id="normal-cost" min="15" max="54" step="0.1" value="29.7"><output id="normal-output"></output></label><div id="normal-chart" class="chart compact"></div><p id="normal-explain" aria-live="polite"></p>''')+'''
<p>An index of <b>170.0</b> means prices represented by the linked CPI are cumulatively 70% above the 2002 reference. It says neither that every product rose 70% nor that inflation this year is 70%. September 2026’s annual rate compares 170.0 with September 2025’s 164.9, not with 100.</p>'''+source('Chapter 2; Chapter 8, paragraphs 8.13–8.20'))

section(3,'A basket with eight branches','From recognizable products to a statistical classification.', '''
<div id="component-panels" class="component-grid"></div>
<p>The CPI covers consumption goods and services within its defined population, geographic and transaction scope. It is not a complete household balance sheet: purchases of financial assets are outside consumption, and buying a house is not treated like buying a loaf of bread.</p>
<div class="note violet"><h3>Owned accommodation is a service flow</h3><p>The Canadian approach measures costs associated with using a dwelling: mortgage interest, replacement cost, property taxes, insurance, maintenance and other owned accommodation expenses. Mortgage principal and the full acquisition price of land and housing are not simply added as current consumption. Rent also needs to distinguish pure price change from changes in dwelling characteristics.</p></div>
<h3>Open the classification</h3><div id="classification" class="classification"></div>
<p>Howlett’s 2026 update reports <b>220 basic aggregates</b> and <b>491 elementary product classes</b>. Product classes intersect geographic strata to form elementary aggregates; 491 should not be mistaken for the total number of product-by-geography cells. The diagram below is a teaching path. The expandable tree above follows the published product codelist, which does not expose every internal elementary index or individual product offer.</p>
<div class="hierarchy-strip"><span>All-items</span><span>8 components</span><span>Intermediate groups</span><span>Basic aggregates</span><span>Elementary aggregates</span><span>Product offers</span></div>
<p class="source">Classification counts: <a href="https://www150.statcan.gc.ca/n1/pub/62f0014m/62f0014m2026005-eng.htm">Rebekah Howlett, 2026 basket update</a>, “Composition of the CPI basket.” Product tree: SDMX structure codelist.</p>'''+source('Chapters 3, 4 and 10'))

section(4,'The weight behind a price change','A small change in a large expense can outweigh a large change in a small one.',eq(r'w_i^b=\frac{E_i^b}{\sum_j E_j^b},\qquad \sum_iw_i^b=1','Eᵢᵇ is spending on category i in expenditure reference period b. Dividing by all in-scope spending converts dollars into a share. The shares add to one before public rounding.')+'''
<p>A category receiving $20 of every $100 has a 20% expenditure share. In a simple fixed-basket comparison, a 10% price rise in that category alone contributes 2 percentage points. This is the same expenditure logic that makes shelter consequential in the Canadian basket.</p>
<div class="controls"><label>Show official shares at <select id="weight-period"><option value="reference">2025 reference-period prices</option><option value="link">April 2026 link-month prices</option></select></label></div><div id="weight-treemap" class="treemap" role="group" aria-label="Eight component expenditure shares"></div><p id="weight-tile-detail" class="hint" aria-live="polite"></p><div id="weight-stack" class="weight-stack"></div><p class="weight-explainer">The first column of weights values the 2025 expenditure basket at 2025 prices; the second updates those prices to April 2026. Their difference is a change in <b>percentage points</b>, not a quantity change or a category inflation rate.</p><div id="weight-table" class="table-wrap"></div>
<p>Reference-period shares describe spending at 2025 prices. Link-month shares revalue the basket at April 2026 prices. For example, food changes from 16.83% to 16.93%, shelter from 28.51% to 28.30%, and transportation from 17.87% to 18.54%. These are different objects. The displayed link shares sum to 100.01% because they are rounded; calculations below normalize them explicitly.</p>
'''+eq(r'\widetilde E_i^{\ell b}=E_i^b\frac{P_i^\ell}{\bar P_i^b},\qquad s_i^{\ell b}=\frac{\widetilde E_i^{\ell b}}{\sum_j\widetilde E_j^{\ell b}}','ℓ denotes the link month and b the annual expenditure period. P̄ᵢᵇ is an annual average price index on a consistent scale. This describes price updating when the category has a stable basket. The official adjustment is performed at detailed levels; a broad component ratio is only an approximation.')+'''
<p>Why divide by the annual average index? If the underlying quantities are constant over year b, annual spending equals that fixed quantity times the sum of its 12 monthly prices. Moving those quantities to the link month therefore uses the link price divided by the annual average price; the common factor of 12 cancels when shares are normalized. The Reference Paper implements this through initial values and subsequent price updating (8.17–8.18).</p>
'''+lab('Explore a basket, then change one expense', '''<p id="shock-starting" class="source"></p><div class="household-context"><div id="shock-illustration"></div><p id="shock-dollar-example"></p></div><div class="controls household-controls"><label>Starting basket <select id="shock-mode"><option value="official">Statistics Canada basket</option><option value="synthetic">Synthetic household</option></select></label><label>Category <select id="shock-category"></select></label><label><span>Expenditure share <output id="shock-weight-value" for="shock-weight"></output></span><input id="shock-weight" aria-label="Expenditure share, percent" type="range" min="0" max="100" step="0.01" value="16.93"></label><label><span>Hypothetical price shock <output id="shock-size-value" for="shock-size"></output></span><input id="shock-size" aria-label="Hypothetical price change, percent" type="range" min="-20" max="40" step="0.5" value="5"></label><button type="button" id="shock-reset">Reset basket</button></div><p id="shock-status" class="scenario-status" aria-live="polite"></p><div id="shock-comparison" class="scenario-comparison"></div><div id="shock-bars" class="chart"></div><p id="shock-result" class="calculation" aria-live="polite"></p><p class="hint">Changing one share redistributes the remainder proportionally across the current other shares. If those shares are all zero, their starting proportions are restored. This is a scenario convention. Published link weights sum to 100.01% because of rounding; calculations normalize the original two-decimal weights at full precision. All other prices are held constant. This model is not the official CPI contribution calculation or a published Canadian inflation rate.</p>''', 'OFFICIAL STARTING WEIGHTS · HYPOTHETICAL PRICE SHOCKS')+'''<p class="source">Weights: <a href="https://doi.org/10.25318/1810000701-eng">Table 18-10-0007-01</a>, 2025, Canada, distribution to selected geographies; <a href="https://www150.statcan.gc.ca/n1/pub/62f0014m/62f0014m2026005-eng.htm">Howlett (2026), Appendix Table 2</a>.</p>'''+source('Chapter 8, paragraphs 8.14–8.18'))

section(5,'From a shelf label to an observation','The target is a comparable transaction, with quantity and quality held in view.', '''
<p>A representative product specifies what to look for. A <b>product offer</b> is more concrete: a particular variety, package, outlet and set of transaction conditions. Geography and retailer selection give the observation a place in the sample. Matched-model collection tries to follow that same offer through time.</p>
<div class="two"><div><h3>Sources and sampling</h3><p>Price collection uses retail establishments, online collection, administrative records and retail scanner transactions. Sampling is adapted to each market; not every observation comes from an identical probability design. Scanner unit values can combine transactions of a sufficiently specific product, while changing the mix of products in a broad average can masquerade as a price change.</p></div><div><h3>Comparability and validation</h3><p>Relevant consumer taxes, product characteristics and transaction conditions matter. A missing price may require imputation from related observations. A replacement model may need an explicit quality adjustment or a comparable replacement procedure. Neither deleting every missing item nor equating a more expensive replacement with pure inflation is defensible.</p></div></div>
'''+player('collection-player','Retail observation pipeline')+lab('A smaller package at the same price','''<div class="split"><div class="package-illustration" id="package-illustration"></div><div><label>New package size, grams <input type="range" id="package-size" min="250" max="600" step="10" value="450"></label><p id="package-result" class="calculation" aria-live="polite"></p></div></div>''')+eq(r'r=\frac{p_1/m_1}{p_0/m_0}=\frac{p_1m_0}{p_0m_1}','p is package price and m is package mass. A $5 package falling from 500 g to 450 g moves from $10/kg to $11.1111/kg. The constant-quantity price relative is 500/450 = 1.1111, an 11.1111% increase, provided other quality is unchanged.')+'''
<div class="note green"><h3>Quality is part of the denominator</h3><p>If a replacement phone costs $550 rather than $500 but has an estimated $40 improvement in features, a simple illustrative adjustment compares $510 with $500: 2% pure price growth. The $40 is a teaching assumption, not an official hedonic estimate. In a hedonic model, log price is related to observed characteristics; estimating their implicit values requires data and model decisions.</p></div>'''+source('Chapters 5 and 7'))

section(6,'The geometry of elementary indices','Average changes before you aggregate expenditures.', eq(r'r_i^{t-1,t}=\frac{p_i^t}{p_i^{t-1}},\qquad J=\left(\prod_{i=1}^{n}r_i\right)^{1/n}=\exp\!\left(\frac1n\sum_{i=1}^{n}\log r_i\right)','n is the number of matched positive price observations. rᵢ is the price relative of observation i. J is a ratio; multiply by 100 to express a period-to-period index with a 100 reference.')+'''
<p>Take logarithms of a product and it becomes a sum. Dividing by n averages proportional changes in log space; exponentiating returns the original scale. For relatives 1.10, 0.90 and 1.20, J = (1.188)^(1/3) = 1.0591, approximately a 5.9105% increase. The arithmetic mean is 1.0667.</p>
'''+eq(r'C=\frac1n\sum_i\frac{p_i^t}{p_i^0},\qquad D=\frac{\sum_i p_i^t}{\sum_i p_i^0}', 'C is Carli, an unweighted arithmetic mean of relatives. D is Dutot, a ratio of arithmetic mean prices. Dutot implicitly gives more weight to higher base prices and requires commensurate product units.')+lab('Edit three matched product offers','''<div class="table-wrap"><table id="elementary-inputs"><caption>Illustrative offers; all prices in dollars per the same specified unit.</caption><thead><tr><th>Offer</th><th>Earlier price</th><th>Later price</th><th>Relative</th><th>Log relative</th></tr></thead><tbody></tbody></table></div><div id="elementary-chart" class="chart"></div><p id="elementary-result" class="calculation" aria-live="polite"></p><button id="reciprocal" type="button">Try reciprocal changes: ×2 and ÷2</button>''')+'''
<p>With relatives 2 and ½, the geometric mean is 1 while Carli is 1.25. Jevons passes the time-reversal test for the same matched sample: reversing the dates produces its reciprocal. Carli generally fails it. By the arithmetic–geometric mean inequality, Carli is at least Jevons for positive relatives. Changing the unit of one product does not affect its relative, but does affect Dutot’s implicit price weights.</p>
<p>Jevons does not make extreme relatives harmless, and it is undefined at nonpositive prices. Equal observation weights are also not household expenditure weights. It is compatible with a unit-elastic substitution interpretation, but does not estimate actual household substitution. The standard elementary formula is often Jevons; special methods for rent, mortgage interest, replacement cost and other classes prevent a universal formula claim.</p>'''+source('Chapter 6, equations (6.1)–(6.2), paragraphs 6.13–6.15; Appendix A'))

section(7,'Four ways to price a basket','The choice of quantities is the decisive difference.',eq(r'P_L^{0,t}=\frac{\sum_i p_i^tq_i^0}{\sum_i p_i^0q_i^0},\qquad P_P^{0,t}=\frac{\sum_i p_i^tq_i^t}{\sum_i p_i^0q_i^t}', 'Laspeyres (L) prices the earlier quantities q⁰ at both sets of prices. Paasche (P) prices later quantities qᵗ at both sets. p⁰ and pᵗ are the corresponding unit prices.')+eq(r'P_F^{0,t}=\sqrt{P_L^{0,t}P_P^{0,t}},\qquad P_{Lo}^{0,t}=\frac{\sum_i p_i^tq_i^b}{\sum_i p_i^0q_i^b}', 'Fisher (F) is the geometric mean of Laspeyres and Paasche. Lowe (Lo) uses fixed quantities from another period b, which need not equal 0 or t.')+'''
<p>These formulas compare two costs of the <em>same</em> quantities within each ratio. Laspeyres is a special Lowe index with b = 0. The Canadian CPI uses a Lowe approach at the upper level because expenditure data arrive after their reference period; the quantities embodied in the latest available expenditure basket predate the prices being compared. Price updating bridges that timing gap.</p>
'''+lab('Use one dataset for all four formulas','''<div class="table-wrap"><table id="formula-inputs"><caption>Synthetic two-good economy; quantity columns are distinct reference baskets.</caption><thead><tr><th>Good</th><th>p⁰</th><th>pᵗ</th><th>q⁰</th><th>qᵗ</th><th>qᵇ</th></tr></thead><tbody></tbody></table></div><div id="formula-results" class="formula-results" aria-live="polite"></div><div id="formula-chart" class="chart compact"></div><div id="formula-work" class="worked"></div>''')+'''
<p>When consumers substitute away from goods whose relative prices rise, a fixed early basket can overstate the cost of attaining the earlier utility level. Under standard optimizing-consumer assumptions, Laspeyres provides an upper bound for a base-utility cost-of-living index; Paasche relates to a different, current-utility comparison. These are conditional statements, not a guarantee that any observed Lowe value exceeds a Fisher index.</p>
<p>Fisher satisfies time reversal and factor reversal for matched positive data. Laspeyres and Paasche are dual when dates are reversed. Additivity for a fixed basket permits consistent aggregation with appropriate expenditure shares; rebasing and separately chain linking broad published series can remove the simple additivity of their displayed levels. The official CPI is neither a Paasche nor a Fisher index.</p>'''+source('Chapter 6, upper-level calculation; Appendix A'))

section(8,'Climbing the aggregation tree','Local geometric means become expenditure-weighted relatives.',eq(r's_i^{0b}=\frac{p_i^0q_i^b}{\sum_jp_j^0q_j^b},\qquad P_{Lo}^{0,t}=\sum_i s_i^{0b}\frac{p_i^t}{p_i^0}', 'Multiply each share by its price relative: the pᵢ⁰ cancels, leaving pᵢᵗqᵢᵇ divided by the common reference expenditure. Summing yields the Lowe cost ratio. Shares and relatives must refer to the same basket and price reference.')+'''
<p>For example, a 60% food branch moving by 5% and a 40% shelter branch moving by 2% give 0.6 × 1.05 + 0.4 × 1.02 = 1.038. The resulting aggregate rises 3.8%. This arithmetic weighting is different from the geometric averaging of product-offer relatives within a typical elementary aggregate.</p>
'''+lab('Trace a single branch to the top','''<label>Follow an elementary group <select id="trace-select"><option value="milk">Milk offers</option><option value="bread">Bread offers</option><option value="rent">Rent service proxy</option></select></label><div id="trace-diagram" class="trace-diagram"></div><div id="trace-work" class="worked" aria-live="polite"></div>''')+player('aggregation-player','Elementary-to-headline aggregation')+'''
<p>The miniature model has two food elementary groups and one shelter proxy. Basic and intermediate nodes are collapsed when they contain only one child, so no extra averaging is implied. In the real classification, each node uses its relevant detailed expenditure distribution. A rent proxy here is a teaching input; official rent estimation uses its own procedures.</p>
<p>To trace influence, multiply the successive branch shares. Milk with half the food branch and food with 60% of the miniature basket has an effective 30% share at the common reference prices. Its contribution to the aggregate change is 0.30 × its elementary percentage change. This exact identity applies to the miniature fixed basket, not automatically to a chain-linked official year-over-year rate.</p>'''+source('Chapter 6, upper-level aggregation; Chapter 4'))

section(9,'New basket. Continuous series.','Link the price movement, not the level of a different shopping list.',eq(r'I_t=I_\ell^{\mathrm{old}}\left(\sum_i s_i^{\ell,b_{new}}\frac{P_i^t}{P_i^\ell}\right),\qquad t>\ell','ℓ is the basket link month. Iℓ is the published old-basket level. The new-basket factor is 1 at ℓ, so multiplying maintains continuity. Pᵢ are detailed index proxies on a consistent scale.')+'''
<p>The May 2026 CPI introduced the 2025 expenditure basket, replacing the 2024 basket. April 2026 is the link month. A new basket’s dollar cost need not equal the old basket’s dollar cost. Chaining removes that artificial discontinuity by comparing each basket with itself at the link.</p>
<div class="controls"><label>Compare reference expenditure years <select id="basket-year"><option>2021</option><option>2022</option><option>2023</option><option selected>2024</option></select></label><span>with 2025</span></div><div id="basket-change" class="chart"></div>
'''+lab('Two baskets at a common link','''<label>Basket after the link <select id="chain-basket"><option value="new">New basket: 30% A, 70% B</option><option value="old">Continue old basket: 70% A, 30% B</option></select></label>'''+player('chain-player','Basket chain linking'))+'''
<p>In the synthetic example the index reaches 120 at the link. In the following period A rises 10% and B falls 2%. The new basket produces 120 × (0.3 × 1.10 + 0.7 × 0.98) = 121.92. Continuing the old shares gives 127.68. Both series equal 120 at the link; their subsequent growth differs because the expenditure patterns differ.</p>
<div class="note peach"><h3>Read the vintage before the rule</h3><p>The 2019 paper describes basket updates every two years or so and SHS-led weights. The 2023 paper documents annual updates beginning with the 2021 update and HFCE-led expenditure estimation, with SHS and supplementary sources. Howlett’s 2026 update uses 2025 HFCE and expanded scanner data for food-from-stores weights. Earlier numerical classification counts and update schedules must not be treated as current.</p></div>
<p>More frequent updates improve relevance but do not turn the CPI into a current-month-quantity index. The reference paper also allows quantities below the basic-class level to be refreshed in some circumstances. This is one reason a “fixed basket” description needs a stated aggregation level.</p>
<p class="source">Sources: <a href="'''+ASSET+'''/cpi-reference-paper-2019-archived.pdf">2019 paper</a>, Chapter 1; <a href="'''+ASSET+'''/cpi-reference-paper.pdf">2023 paper</a>, 8.6–8.20; <a href="https://www150.statcan.gc.ca/n1/pub/62f0014m/62f0014m2026005-eng.htm">Howlett (2026)</a>. Official weight bars use Table 18-10-0007-01.</p>''')

section(10,'The level and the speed of change','Disinflation can coexist with a rising cost of the basket.',eq(r'\pi_t^{MoM}=100\left(\frac{I_t}{I_{t-1}}-1\right),\quad \pi_t^{YoY}=100\left(\frac{I_t}{I_{t-12}}-1\right)', 'π is percentage price growth. Month-over-month compares adjacent months; year-over-year compares the same month one year earlier. Both use index ratios, not index-point differences.')+eq(r'\pi_{a,b}=100\left(\frac{I_b}{I_a}-1\right),\qquad \frac{I_b}{I_a}=\prod_{t=a+1}^{b}\left(1+\frac{\pi_t^{MoM}}{100}\right)', 'a and b are selected months. Cumulative inflation compounds monthly ratios. Adding rounded monthly percentages is generally only an approximation.')+'''
<div class="controls"><label>Canadian series <select id="history-series"></select></label><label>View <select id="history-metric"><option value="level">Index level</option><option value="yoy">Year-over-year, %</option><option value="mom">Month-over-month, %</option></select></label><label>Start year <select id="history-start"><option>1914</option><option>1960</option><option>2002</option><option>2010</option><option selected>2019</option><option>2024</option></select></label></div><div id="history-chart" class="chart large"></div><p id="history-detail" class="chart-detail" aria-live="polite"></p><details><summary>View the plotted observations as a table</summary><div id="history-table" class="table-wrap"></div></details>
<p>In September 2026, 170.0 − 169.8 = 0.2 index points, but 100 × (170.0/169.8 − 1) = 0.1178%. Index points and percent are distinct units. Over the year, 170.0 − 164.9 = 5.1 index points corresponds to 3.0928% inflation.</p>
'''+player('disinflation-player','Disinflation and price levels')+'''
<p><b>Disinflation</b> means inflation slows. In the teaching animation, successive increases of 6%, 3% and 1% lift a 100.0 index to 106.0, 109.2 and 110.3. The price level keeps rising. <b>Deflation</b> means the relevant inflation rate is negative. A lower annual rate can also reflect a high comparison level a year earlier—a base effect—even if this month’s prices increased.</p>'''+official())

section(11,'Separate a season from a trend','Published adjustment is an estimated statistical procedure, not subtraction of an obvious wave.',eq(r'Y_t=T_t+S_t+R_t,\qquad Y_t=T_tS_tR_t\ \text{(multiplicative)}','Y is the observed series; T is trend-cycle; S is seasonal variation; R is irregular variation. Additive components share Y’s units. Multiplicative components are factors; logs convert their product into a sum.')+'''
<p>Clothing sales, holiday travel and fresh produce availability can generate recurring patterns. Adjustment estimates the predictable seasonal component so adjacent-month changes are easier to interpret. In the synthetic additive model below, the seasonal term is known because we supplied it. In real data it must be estimated, with calendar effects, outliers and model choices.</p>
'''+lab('Remove a known synthetic season','''<label>Seasonal amplitude, index points <input type="range" id="season-amplitude" min="0" max="12" step="0.5" value="6"></label><div id="synthetic-season" class="chart"></div><p id="season-result" class="calculation"></p>''')+'''
<h3>Now use the published Canadian adjustment</h3><div class="controls"><label>Series <select id="season-series"></select></label></div><div id="actual-season" class="chart"></div><div id="season-actual-table" class="table-wrap"></div>
<p>The downloaded 2023 Reference Paper describes <b>X-12-ARIMA</b> and direct adjustment of the all-items series and selected aggregates. It does not imply that adjusted headline CPI is the weighted sum of adjusted components. The release notes permit revision of the previous month and annual revision of the prior three years. The comparison here retrieves Table 18-10-0006-01; it does not rerun the official adjustment. This study has not verified whether the production implementation has changed since that paper.</p>
<p>Unadjusted August–September 2026 CPI changes from 169.8 to 170.0; adjusted CPI changes from 169.4 to 170.0. The resulting rates, 0.1178% and 0.3542%, answer different questions. For indexation, the release recommends unadjusted indices. Seasonal revision vintages must be retained when comparing historical releases.</p>
<p class="source">Sources: <a href="https://doi.org/10.25318/1810000601-eng">Table 18-10-0006-01</a>; <a href="'''+ASSET+'''/cpi-september-report.pdf#page=8">September release, Table 3</a>; Reference Paper, 10.41–10.44.</p>''')

section(12,'A rate is not a contribution','A contribution measures how much of aggregate growth comes from one branch.',eq(r'A_t=\sum_i E_i^0r_i^t\ \Longrightarrow\ g=100\left(\frac{A_t}{A_0}-1\right)=\sum_i100s_i^0(r_i^t-1)', 'A is aggregate fixed-basket expenditure. Eᵢ⁰ is reference expenditure, sᵢ⁰ = Eᵢ⁰/A₀ and rᵢᵗ is the matching price relative. Each term is a percentage-point contribution.')+eq(r'c_i^{u,t}=100\frac{E_i^0r_i^u}{\sum_jE_j^0r_j^u}\left(\frac{r_i^t}{r_i^u}-1\right)', 'For a later comparison u → t within the same fixed basket, use shares price-updated to u, not the original sᵢ⁰. Contributions sum exactly to aggregate growth for that basket. Crossing a basket link requires consistent linked segments and detailed contributions.')+lab('A fixed-basket contribution waterfall','''<div class="controls"><label>Gasoline shock, % <input id="gas-shock" type="range" min="-40" max="60" step="1" value="20"></label><label>Gasoline share, % <input id="gas-share" type="range" min="1" max="15" step="0.5" value="5"></label></div><div id="waterfall" class="chart"></div><p id="waterfall-result" class="calculation" aria-live="polite"></p><p class="hint">Synthetic shares: gasoline, other transport, food, shelter and other consumption. They are not official September 2026 contributions.</p>''')+'''
<h3>What the September release actually identifies</h3><div class="two"><div class="note green"><h4>Upward annual contributors</h4><p>Gasoline (+27.8%); rent (+2.8%); air transportation (+19.4%); food from restaurants (+3.1%); property taxes and special charges (+5.6%).</p></div><div class="note peach"><h4>Downward annual contributors</h4><p>Homeowners’ replacement cost (−1.9%); natural gas (−6.8%); other owned accommodation expenses (−1.5%); fresh vegetables (−2.9%); financial services (−0.8%).</p></div></div>
<p>Those numbers are the contributors’ own annual price changes, <b>not percentage-point contributions</b>. Table 5 ranks contributors but does not publish their percentage-point amounts. Gasoline led the acceleration: its annual rate rose from 22.8% in August to 27.8% in September. Moderation in travel tours and groceries partly offset the acceleration. No numerical official contribution is inferred here from that prose.</p>
<p class="source">Official contributor names and rates: <a href="'''+ASSET+'''/cpi-september-report.pdf#page=10">Statistics Canada, September 2026 release, Table 5</a>. Waterfall: original fixed-basket teaching calculation.</p>'''+source('Chapter 2, analytical uses; Chapter 6, aggregation'))

section(13,'Look inside the distribution','Exclusions, trimming, a weighted median and a common factor are different filters.', '''
<p>Headline CPI covers the full basket. Excluding gasoline, excluding energy, and excluding food and energy define alternative baskets. They remove named categories whether their prices are unusually volatile this month or not. CPI-trim and CPI-median instead use the weighted distribution of component price changes, after the required tax and seasonal adjustments.</p>
'''+eq(r'F(x)=\sum_iw_i\mathbf1(x_i\le x),\quad m=\inf\{x:F(x)\ge0.5\},\quad \tau=\frac1{0.6}\int_{0.2}^{0.8}F^{-1}(u)\,du','xᵢ is a component monthly percentage change; wᵢ are weights summing to one. m is the weighted median. τ is the mean of the middle 60% of expenditure weight; a boundary category can be partially retained.')+lab('Trim expenditure weight, not the number of dots','''<label>Move the high-tail price change, % <input id="core-outlier" type="range" min="2" max="30" step="0.5" value="12"></label><div id="core-distribution" class="chart"></div><div id="core-result" class="worked" aria-live="polite"></div><div id="core-mini-table" class="table-wrap"></div><p class="hint">Eight synthetic categories of unequal weight. Orange tails are removed by cumulative expenditure share. Boundary weights are split exactly.</p>''')+'''
<p>These formulas describe one month’s miniature distribution. Official annual CPI-trim and CPI-median require monthly component histories, the official weighting and adjustment conventions, chaining and annual comparison. An annual median of published component annual rates is not the official annual CPI-median.</p>
'''+eq(r'x_{it}=\lambda_i f_t+\varepsilon_{it}','A one-factor teaching representation for CPI-common: fₜ is a latent common movement, λᵢ a category loading, and εᵢₜ a category-specific residual. It explains the factor-model idea, not the complete official estimation specification.')+'''
<p>CPI-common seeks shared movements rather than discarding named categories or ranking only this month’s changes. Estimated factors can change as history expands, making revisions conceptually different from revisions to seasonal factors.</p>
<div id="core-official" class="stat-grid three"></div><div id="special-core" class="table-wrap"></div>
<p class="source">September annual core rates match <a href="'''+ASSET+'''/cpi-september-report.pdf#page=9">Statistics Canada’s release, Table 4</a> and an independent extraction of the <a href="https://www.bankofcanada.ca/rates/price-indexes/cpi/">Bank of Canada CPI table</a>. The release cites <a href="https://doi.org/10.25318/1810025601-eng">Table 18-10-0256-01</a>; tax and seasonal treatments are described in its footnotes. These are Level B source matches, not a reconstruction of the core estimation. Historical vintages are identified by the release as Table 18-10-0259-01.</p>''')

section(14,'Inflation has a geography','Compare movements within each geography, not the apparent cost of living between them.', '''
<div id="geography-tiles" class="geo-tiles" aria-label="Province and territorial-city inflation selector"></div><div class="controls"><label>All available geographies <select id="geo-select"></select></label></div><div id="geo-stats" class="stat-grid three"></div><div id="geo-chart" class="chart"></div><div id="geo-components" class="table-wrap"></div>
<p>Different housing markets, energy prices, taxes, transportation patterns and expenditure shares can produce different regional price movements. A region’s index of 178 does not establish that it is more expensive than a region at 163: the indices track changes from their own reference baskets, not comparable dollar price levels.</p>
<p>Whitehorse, Yellowknife and Iqaluit are territorial <em>city</em> series; they do not stand for complete territorial coverage. Iqaluit’s reference is December 2002 = 100, while most displayed series use annual 2002 = 100. Ratios within a consistently based series still yield valid inflation rates. Historical coverage and component availability vary.</p>
<p>National CPI combines geographically weighted expenditures and price changes through the official hierarchy. An unweighted average of provincial index levels has no such interpretation. The tile arrangement is a schematic selector, not a geographic map.</p>'''+official())

section(15,'Turn nominal dollars into purchasing power','Choose the dates before interpreting a “real” amount.',eq(r'V_t^{\mathrm{real},b}=V_t^{\mathrm{nominal}}\frac{I_b}{I_t},\qquad V_{b\to t}^{\mathrm{equiv}}=V_b\frac{I_t}{I_b}','Vᵗ is money received or spent at date t. Multiplying by Iᵇ/Iᵗ expresses it in base-month b purchasing-power dollars. The reverse ratio gives the later nominal amount needed to match an earlier purchasing power.')+lab('Salary, pension, transfer or contract comparison','''<div class="controls"><label>Context <select id="money-context"><option>Salary</option><option>Pension</option><option>Government transfer</option><option>Contract payment</option><option>Household expenditure</option></select></label><label>Earlier nominal amount, $ <input id="money-value" type="number" min="0" step="100" value="60000"></label><label>Earlier month <select id="money-base"></select></label><label>Later month <select id="money-target"></select></label></div><div id="money-result" class="worked" aria-live="polite"></div><div id="money-chart" class="chart compact"></div>''','OFFICIAL CPI • USER-SUPPLIED AMOUNT')+'''
<p>If nominal wages grow by factor N while CPI grows by factor P, real wage growth is N/P − 1, not exactly the difference between the two growth rates. At 4% nominal growth and 3% inflation, the real increase is 1.04/1.03 − 1 = 0.9709%.</p>
<p>CPI adjustment uses the average expenditure structure represented by the index. A household facing a rent increase, buying a first home or spending an unusually high share on health services can have a different experience. Pension, transfer and contract rules may use annual averages, lags, caps or prescribed reference months. The calculator illustrates CPI conversion and does not determine a program’s actual legal entitlement.</p>'''+official())

section(16,'Audit September 2026','A transparent ladder from verified arithmetic to unavailable microdata.', '''
<p class="lead">The data pipeline scanned 1,154,918 SDMX observations, extracted 499 national and regional series, and compared them with tables independently read from the downloaded September release.</p>
<div class="four audit-levels"><div><b>A</b><h3>Arithmetic</h3><p>Compute rates from official public index observations.</p></div><div><b>B</b><h3>Series match</h3><p>Match extracted observations against the release tables.</p></div><div><b>C</b><h3>Reconstruction</h3><p>Approximate aggregation using rounded public weights and indices.</p></div><div><b>D</b><h3>Unavailable</h3><p>Retail-price construction needs unpublished inputs and procedures.</p></div></div>
<h3>The headline, with every input exposed</h3>'''+eq(r'100\left(\frac{170.0}{164.9}-1\right)=3.0928\%\to3.1\%,\quad100\left(\frac{170.0}{169.8}-1\right)=0.1178\%\to0.1\%')+eq(r'100\left(\frac{170.0}{169.4}-1\right)=0.3542\%\to0.4\%\quad\text{(seasonally adjusted)}')+'''
<p>The one-decimal index inputs are already rounded. Extra digits in these ratios are calculation precision, not new information about the unrounded official index. For a displayed index a, the unrounded value is approximately in [a − 0.05, a + 0.05). A rate reconstructed from two displayed inputs therefore has an interval of possibilities.</p>'''+eq(r'100\left(\frac{a-0.05}{b+0.05}-1\right)\ \le\ \pi\ \lesssim\ 100\left(\frac{a+0.05}{b-0.05}-1\right)','The bounds follow because a/b increases with its numerator and decreases with its positive denominator. These are rounding bounds, not sampling confidence limits.')+'''
<div id="rounding-work" class="worked"></div><h3>Major components, special aggregates and products</h3><p>Component levels and annual rates, exclusions, energy, goods, services, durable, semi-durable and non-durable goods are checked against release Table 1. Gasoline is included in that comparison. Groceries, rent and additional products have independently calculated rates; rows without a separate release-table comparator are labelled accordingly. All available geography headline rates are calculated, with comparisons for the provinces and three territorial cities in Table 2.</p>
<div id="replication-chart" class="chart"></div><div id="audit-stats" class="stat-grid three"></div>
<div class="controls"><label>Find a series or geography <input type="search" id="audit-search" placeholder="e.g. gasoline or Ontario"></label><label>Replication level <select id="audit-level"><option value="all">All levels</option><option>A</option><option>B</option><option>C</option><option>D</option></select></label><label>Metric <select id="audit-metric"><option value="all">All metrics</option><option>YoY</option><option>MoM</option><option>SA MoM</option><option>NSA index</option><option>SA index</option></select></label></div><p id="audit-count" class="hint"></p><div id="audit-table" class="table-wrap audit-table" tabindex="0" aria-label="Scrollable replication audit"></div>
<h3>Attempt the upper-level reconstruction</h3>'''+eq(r'\widehat I_{Sep26}=I_{Apr26}\sum_{i=1}^{8}\widetilde s_i^{Apr26,2025}\frac{I_{i,Sep26}}{I_{i,Apr26}}','The tilde denotes normalized, publicly rounded link-month shares. This is a Level C approximation using eight broad published components. It assumes their public linked relatives adequately proxy a common new-basket aggregate.')+'''<div id="aggregation-work" class="worked"></div><div id="aggregation-inputs" class="table-wrap"></div>
<p>The calculation is anchored at the official April headline level; it is not an independent reconstruction of the 2002-to-April history. A cross-basket annual approximation also uses April 2025 link shares for the older segment: the old-basket relative from September 2025 to April 2026 is multiplied by the new-basket April-to-September factor. Both segments use rounded broad components.</p>
<p>The remaining discrepancy cannot be assigned uniquely to one cause. Published index rounding, rounded weights, aggregation at only eight components, independent chain linking of components and changes below their basic classes all limit this reconstruction. Full internal elementary weights, compatible unlinked detailed relatives, microdata, imputations, quality adjustments and estimation decisions would be needed to reproduce the official construction. A matching rounded growth rate alone would not demonstrate that those steps were reproduced.</p>
<div class="downloads"><a href="'''+ASSET+'''/validation/replication.csv" download>Download audit CSV ↗</a><a href="'''+ASSET+'''/validation/replication.json">Machine-readable report ↗</a><a href="'''+ASSET+'''/data/metadata/manifest.json">Dataset manifest ↗</a><a href="'''+ASSET+'''/scripts/validate_cpi_replication.py">Validation Python ↗</a></div>
<p class="source">Comparators: <a href="'''+ASSET+'''/cpi-september-report.pdf#page=7">release PDF, Tables 1–3, pp. 7–8</a>. Independent inputs: SDMX 18-10-0004-01 and CSV 18-10-0006-01. Tolerance for rate comparisons: ±0.05 percentage points; index comparisons require numerical equality (1e−8 floating tolerance). The CSV reports every numerical difference. Core rates are source transcriptions and are not counted as independently reconstructed core measures.</p>''')

section(17,'What uncertainty does—and does not—mean','A known reconstruction difference is not a confidence interval.', '''
<div class="two"><div><h3>Representation and measurement</h3><p>Coverage, selected outlets, geography and household heterogeneity affect what the index represents. Product turnover, quality adjustment, package sizes and missing observations affect the comparison being measured. Outlet substitution and shifting expenditure patterns can make an old basket less representative even when its arithmetic is correct.</p></div><div><h3>Formula, rounding and revision</h3><p>Different elementary formulas embody different implicit weights and substitution properties. Published rounding limits reverse engineering. Headline unadjusted CPI generally follows a non-revision policy, subject to corrections; seasonal and core estimates can be revised. Long comparisons span many baskets, products and methods, so their meaning is broader than repricing one unchanged century-old shopping list.</p></div></div>
'''+lab('Sample prices from a known artificial population','''<div class="controls"><label>Sample size <input id="sample-size" type="range" min="3" max="180" step="1" value="20"></label><button id="sample-again" type="button">Draw another sample</button></div><div id="sample-chart" class="chart"></div><p id="sample-result" class="calculation" aria-live="polite"></p><p class="hint">Deterministic pseudo-random draws from 240 synthetic price relatives. This is an equal-probability teaching experiment, not Statistics Canada’s sample design or a confidence interval for CPI.</p>''')+'''
<p>The complete synthetic population has a known geometric-mean price change. A sample’s geometric mean varies with the selected offers. Increasing sample size reduces typical dispersion, though a single larger draw need not be closer. The chart compares 60 simulated estimates at the selected size and highlights the current draw. Finite-population sampling is without replacement within each draw.</p>
<p>The Reference Paper describes mixed sampling strategies and discusses reliability without supporting a simple universal sampling variance for the headline CPI. No official 95% interval is invented here. The −0.0705 index-point Level C discrepancy is an observed difference between two calculations. It is not an estimate of official measurement error and is not evidence that the published CPI is wrong.</p>'''+source('Chapter 9; Chapter 5 on sample design'))

section(18,'From prices to inflation, connected','Ten steps, with the boundary of reproducibility kept visible.',player('synthesis-player','Complete CPI construction')+'''
<div class="two"><div class="note green"><h3>What this study reproduces</h3><p>Public index extraction, monthly and annual growth arithmetic, source-table matching, regional comparisons and CPI deflation of nominal values. The teaching models independently implement elementary formulas, fixed-basket aggregation, linking, exact synthetic contributions and weighted trimming.</p></div><div class="note peach"><h3>What remains an estimate or a source reading</h3><p>Eight-component official aggregation is approximate. Core values are read from the release. Published seasonally adjusted indices are retrieved rather than re-estimated. Unpublished product-offer construction, full quality adjustment, internal weights and core estimation are not independently replicated.</p></div></div>
<p>The central connection is a sequence of ratios: comparable prices give elementary change; detailed expenditure shares aggregate those changes; a link connects baskets; ratios of the linked index give inflation. Understanding where the weights, comparisons and reference periods change is more useful than memorizing a single “CPI formula.”</p>'''+source('Chapters 3–10'))

def references():
 return '''<section id="references" class="references"><span class="eyebrow">REFERENCES & DATA PROVENANCE</span><h2>A trail back to the evidence</h2>
<ol><li><b>Statistics Canada (February 20, 2023).</b> <i>The Canadian Consumer Price Index Reference Paper</i>, Catalogue 62-553-X. Chapters 3–10 and Appendix A. <a href="'''+ASSET+'''/cpi-reference-paper.pdf">Preserved PDF</a>; <a href="https://www150.statcan.gc.ca/n1/pub/62-553-x/2023001/chap-8-eng.htm">online Chapter 8</a>. The originally supplied index-eng.htm URL returned 404; it is retained in the acquisition manifest. The local PDF supplies the complete methodological evidence.</li>
<li><b>Statistics Canada (February 27, 2019).</b> <i>The Canadian Consumer Price Index Reference Paper</i>, Catalogue 62-553-X. Archived methods and update schedule. <a href="'''+ASSET+'''/cpi-reference-paper-2019-archived.pdf">Preserved archived PDF</a>.</li>
<li><b>Rebekah Howlett (June 15, 2026), Statistics Canada.</b> <i>An Analysis of the 2026 Consumer Price Index Basket Update, Based on 2025 Expenditures</i>, Prices Analytical Series, 62F0014M2026005. Classification, weights, data sources, Appendix Tables 1–2. <a href="https://www150.statcan.gc.ca/n1/pub/62f0014m/62f0014m2026005-eng.htm">Original publication</a>; <a href="'''+ASSET+'''/references/basket-update-2026.html">saved reference</a>.</li>
<li><b>Statistics Canada (October 19, 2026).</b> <i>Consumer Price Index, September 2026</i>, The Daily, Catalogue 11-001-X. <a href="https://www150.statcan.gc.ca/n1/daily-quotidien/261019/dq261019a-eng.htm">Release</a>; <a href="'''+ASSET+'''/cpi-september-report.pdf">preserved PDF</a>. Tables 1–5 supply independent comparisons, core rates and contributor names. <a href="https://www150.statcan.gc.ca/n1/daily-quotidien/261019/t001a-eng.htm">Detailed Table 1</a>; <a href="https://www150.statcan.gc.ca/n1/daily-quotidien/261019/t003a-eng.htm">Detailed Table 3</a>.</li>
<li><b>Statistics Canada.</b> <i>Consumer Price Index, monthly, not seasonally adjusted</i>, Table 18-10-0004-01. <a href="https://doi.org/10.25318/1810000401-eng">DOI: 10.25318/1810000401-eng</a>. Existing SDMX files: snapshot through August 2024 plus 25 monthly updates to September 2026. Original retrieval dates unknown; each SDMX Prepared date and SHA-256 are retained in the manifest.</li>
<li><b>Statistics Canada.</b> <i>Consumer Price Index, monthly, seasonally adjusted</i>, Table 18-10-0006-01. <a href="https://doi.org/10.25318/1810000601-eng">DOI: 10.25318/1810000601-eng</a>. Downloaded full CSV ZIP; page filters at September 2026. Adjusted data may be subject to revision.</li>
<li><b>Statistics Canada.</b> <i>Basket weights of the Consumer Price Index</i>, Table 18-10-0007-01. <a href="https://doi.org/10.25318/1810000701-eng">DOI: 10.25318/1810000701-eng</a>. Canada, distribution to selected geographies, reference- and link-price weights; years 2021–2025 extracted.</li>
<li><b>Statistics Canada.</b> <i>Consumer Price Index, annual average</i>, Table 18-10-0005-01. <a href="https://doi.org/10.25318/1810000501-eng">DOI: 10.25318/1810000501-eng</a>. Related reference, not downloaded or used as a numerical input. An annual average CPI is the arithmetic mean of the year’s 12 monthly index levels, distinct from a December-to-December rate.</li>
<li><b>Statistics Canada / Bank of Canada definitions.</b> <i>CPI statistics, measures of core inflation and other related statistics</i>, Table 18-10-0256-01. <a href="https://doi.org/10.25318/1810025601-eng">DOI: 10.25318/1810025601-eng</a>. September values sourced through release Table 4 and independently matched to the <a href="https://www.bankofcanada.ca/rates/price-indexes/cpi/">Bank of Canada CPI page</a>; <a href="'''+ASSET+'''/references/bank-of-canada-cpi.html">saved Bank reference</a>. Certificate verification remained enabled during retrieval.</li>
<li><b>Statistics Canada, Consumer Prices Division.</b> <i>Concordance table</i>, survey 2301, document D66 V1. <a href="https://www.statcan.gc.ca/en/statistical-programs/document/2301_D66_V1">Original</a>; <a href="'''+ASSET+'''/references/concordance.html">saved reference</a>. Maps older CPI publication tables to current statistical tables; it is not a product-offer dataset.</li></ol>
<h3>Implementation and provenance</h3><p>All SVG illustrations, chart compositions and teaching datasets are original to this study. Official observations remain Statistics Canada data. Python streaming extraction maps SDMX dimension codes and vectors, preserves available flags, and compares the result against separately extracted PDF tables. No official chart is copied. Local KaTeX 0.16.11 renders mathematics under its <a href="'''+ASSET+'''/vendor/katex-LICENSE">MIT licence</a>. The site runs from static assets and makes no remote API calls.</p>
<p>Source acquisition records contain actual UTC retrieval timestamps; the requested editorial creation date is October 30, 2026. The empirical snapshot ends at the October 19 release. Read <a href="'''+ASSET+'''/README.md">README and reproduction instructions</a>, <a href="'''+ASSET+'''/data/metadata/manifest.json">manifest</a>, <a href="'''+ASSET+'''/data/processed/series-map.csv">series mapping</a> and <a href="'''+ASSET+'''/validation/replication.md">validation narrative</a>. No original download was altered.</p><a class="back-top" href="#top">Back to the beginning ↑</a></section>'''

def main():
 refine_chapters(SECTIONS,ASSET,eq,lab,player)
 nav=''.join(f'<a href="#s{n:02}" data-section="s{n:02}"><span>{n:02}</span>{escape(t)}</a>' for n,t,_,_ in SECTIONS)
 mobile=''.join(f'<option value="s{n:02}">{n:02} · {escape(t)}</option>' for n,t,_,_ in SECTIONS)
 content=''.join(f'<section id="s{n:02}" class="chapter"><header class="chapter-header"><span class="chapter-number">{n:02}</span><div><h2>{escape(t)}</h2><p>{escape(deck)}</p></div></header>{b}</section>' for n,t,deck,b in SECTIONS)
 html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="An interactive, mathematically rigorous and reproducible study of Canada’s CPI, with September 2026 source-data validation."><title>Canada's Consumer Price Index: From Everyday Prices to the Mathematics of Inflation</title><link rel="stylesheet" href="'''+ASSET+'''/vendor/katex.min.css"><link rel="stylesheet" href="'''+ASSET+'''/styles.css"><script defer src="'''+ASSET+'''/vendor/katex.min.js"></script><script defer src="'''+ASSET+'''/data/processed/cpi-data.js"></script><script defer src="'''+ASSET+'''/validation/replication-data.js"></script><script defer src="'''+ASSET+'''/app.js"></script></head><body><a class="skip" href="#s01">Skip to the study</a><div id="top" class="topline"><span>NARESH PANE / RESEARCH NOTES</span><span>ECONOMICS · METHODS · REPLICATION</span></div>
<header class="hero"><div class="hero-copy"><span class="eyebrow">AN INTERACTIVE RESEARCH MONOGRAPH · 18 CHAPTERS</span><h1>Canada's Consumer Price Index:<br><em>From Everyday Prices to the Mathematics of Inflation</em></h1><p class="subtitle">An interactive exploration of Canada's monthly Consumer Price Index, from household shopping baskets and representative products to elementary price indices, expenditure weights, index-number theory, inflation decomposition, seasonal adjustment, and empirical replication using Statistics Canada data.</p></div><aside class="metadata"><div class="metadata-title">THE RESEARCH RECORD</div><dl><dt>Created</dt><dd>October 30, 2026</dd><dt>Harness</dt><dd>Codex on Windows</dd><dt>Latest CPI observation</dt><dd>September 2026</dd><dt>Latest release</dt><dd>October 19, 2026</dd><dt>Research focus</dt><dd>Mathematical and empirical replication</dd></dl><div id="hero-basket" aria-label="A miniature household basket"></div><p>Every number needs a comparison.<br>Every comparison needs a method.</p></aside></header>
<div class="opening"><p class="lead">One familiar question. An intricate measurement system.</p><p>Follow a receipt into the mathematics, then test the mathematics against public Canadian data. Green teaching panels expose the calculations; blue source notes lead back to evidence. Synthetic experiments are labelled, and the audit distinguishes arithmetic verification from full index construction.</p><div id="headline-stats" class="stat-grid four"></div><p class="source">September 2026, Canada. Source: Statistics Canada, The Daily, October 19, 2026, Tables 1 and 3. An index of 170.0 represents a cumulative 70% increase relative to the 2002 reference, across successive baskets; it is not a 70% annual inflation rate.</p></div>
<div class="mobile-nav"><label for="chapter-jump">In this study</label><select id="chapter-jump">'''+mobile+'''</select><span id="reading-progress"></span></div><div class="study-layout"><aside class="contents"><div class="eyebrow">FOLLOW THE ARGUMENT</div><nav aria-label="Study chapters">'''+nav+'''<a href="#references"><span>↗</span>References & data</a></nav><a class="contents-download" href="'''+ASSET+'''/README.md">Reproduce this study ↗</a></aside><main>'''+content+references()+'''</main></div><footer><span>Canada’s CPI · From everyday prices to inflation</span><span>Static, local-first research · October 2026</span></footer><noscript><p class="noscript">The full text and mathematical source are readable without JavaScript. Interactive figures and the embedded data audit require JavaScript; downloadable datasets and validation reports remain available.</p></noscript></body></html>'''
 html=refine_shell(html,ASSET)
 (ROOT.parent/(ASSET+'.html')).write_text(html,encoding='utf-8')
 print(f'Built {len(SECTIONS)} chapters; {len(html):,} HTML characters.')
if __name__=='__main__':main()
